const items = $input.all();
const output = [];
for (let i = 0; i < items.length; i++) {
  const keys = Object.keys(items[i].binary ?? {});
  if (keys.length !== 1) throw new Error('Envie exatamente um arquivo PDF.');
  const meta = items[i].binary[keys[0]];
  const buffer = await this.helpers.getBinaryDataBuffer(i, keys[0]);
  if (!buffer.length) throw new Error('O arquivo está vazio.');
  if (buffer.length > 20 * 1024 * 1024) throw new Error('O PDF deve ter no máximo 20 MB.');
  if (buffer.subarray(0, 1024).toString('latin1').indexOf('%PDF-') < 0) throw new Error('O arquivo enviado não é um PDF válido.');
  output.push({json: {file: buffer.toString('base64'), fileType: 0, fileName: meta.fileName || 'documento.pdf', fileSize: buffer.length}, pairedItem: {item: i}});
}
return output;

